// src/pages/Home.jsx
import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import "../styles/style.css";

export default function Home() {
  const [loggedUser, setLoggedUser] = useState(null);

  useEffect(() => {
    const user = JSON.parse(localStorage.getItem("loggedInUser"));
    if (user) setLoggedUser(user);
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("loggedInUser");
    setLoggedUser(null);
  };

  return (
    <div className="home-container">
      {/* Nome da empresa clicável */}
      <Link to="/" id="companyName">
        Bella Nails Studio
      </Link>

      <p>Manicure and Pedicure</p>
      <p>
        Schedule your appointments easily and quickly. Login or register to get
        started!
      </p>

      <div id="actionButtons">
        {!loggedUser ? (
          <>
            <Link className="nav-button" to="/signIn">
              Sign In
            </Link>
            <Link className="nav-button" to="/signUp">
              Sign Up
            </Link>
            <Link className="nav-button" to="/admin-login">
              Admin Sign In
            </Link>
          </>
        ) : (
          <>
            <p>Welcome, {loggedUser.name}!</p>
            <Link className="nav-button" to="/schedule">
              Go to Schedule
            </Link>
            <button onClick={handleLogout} className="nav-button">
              Logout
            </button>
          </>
        )}
      </div>
    </div>
  );
}
